/**
 * An open workspace database.
 */
public protocol CoreWorkspaceProtocol: AnyObject, Sendable {
    
    /**
     * Creates a condition as one "New Condition" step; returns its id.
     */
    func createCondition(workspaceId: String, name: String, isLocation: Bool, nowMs: Int64) throws  -> String
    
    /**
     * Creates a folder as one "New Folder" step.
     */
    func createFolder(workspaceId: String, name: String, parentFolderId: String?, nowMs: Int64) throws  -> CreatedItem
    
    /**
     * Creates a list as one "New List" step.
     */
    func createList(workspaceId: String, name: String, folderId: String?, nowMs: Int64) throws  -> CreatedItem
    
    /**
     * Creates a task as one "New Task" step and returns its id.
     */
    func createTask(task: NewTask, nowMs: Int64) throws  -> String
    
    /**
     * Deletes a folder as one "Delete Folder" step; its lists move to the top.
     */
    func deleteFolder(id: String) throws 
    
    /**
     * Deletes a list and its tasks as one "Delete List" step.
     */
    func deleteList(id: String) throws  -> DeletedList
    
    /**
     * Deletes a task and its subtree as one "Delete Task" step.
     */
    func deleteTask(id: String) throws  -> DeletedTask
    
    /**
     * The task and list the next undo (`for_undo`) or redo affects.
     */
    func historyTarget(forUndo: Bool) throws  -> HistoryTarget
    
    /**
     * Indents a task under the sibling above as one "Indent Task" step.
     */
    func indentTask(id: String, nowMs: Int64) throws 
    
    /**
     * Moves a folder into another (or to the top) as one "Move Folder" step.
     */
    func moveFolder(id: String, parentFolderId: String?, nowMs: Int64) throws 
    
    /**
     * Moves a folder among its siblings as one "Reorder Folder" step.
     */
    func moveFolderWithinSiblings(id: String, offset: Int32, nowMs: Int64) throws 
    
    /**
     * Moves a list into a folder (or to the top) as one "Move List" step.
     */
    func moveList(id: String, folderId: String?, nowMs: Int64) throws 
    
    /**
     * Moves a list among its siblings as one "Reorder List" step.
     */
    func moveListWithinFolder(id: String, offset: Int32, nowMs: Int64) throws 
    
    /**
     * Moves a task and its subtree as one "Move Task" step.
     */
    func moveTask(id: String, listId: String, parentTaskId: String?, toVisibleRoot: Bool, nowMs: Int64) throws 
    
    /**
     * Drops a task before a sibling, and into a board column, as one
     * "Reorder Task" step.
     */
    func moveTaskBefore(id: String, targetId: String, kanbanColumn: String?, nowMs: Int64) throws 
    
    /**
     * Moves a task to the top of its siblings as one "Reorder Task" step.
     */
    func moveTaskToStart(id: String, nowMs: Int64) throws 
    
    /**
     * Moves a task among its siblings as one "Reorder Task" step.
     */
    func moveTaskWithinSiblings(id: String, offset: Int32, nowMs: Int64) throws 
    
    /**
     * Outdents a task to follow its parent as one "Outdent Task" step.
     */
    func outdentTask(id: String, nowMs: Int64) throws 
    
    /**
     * Drops a folder before another, in a parent, as one "Reorder Folder" step.
     */
    func placeFolder(id: String, beforeId: String?, parentFolderId: String?, nowMs: Int64) throws 
    
    /**
     * Drops a list before another, in a folder, as one "Reorder List" step.
     */
    func placeList(id: String, beforeId: String?, folderId: String?, nowMs: Int64) throws 
    
    /**
     * Puts back the most recently undone step.
     */
    func redo() throws  -> String?
    
    /**
     * What redo would put back.
     */
    func redoableLabel() throws  -> String?
    
    /**
     * Renames a folder as one "Rename Folder" step.
     */
    func renameFolder(id: String, name: String, nowMs: Int64) throws 
    
    /**
     * Renames a list as one "Rename List" step.
     */
    func renameList(id: String, name: String, nowMs: Int64) throws 
    
    /**
     * Saves a condition as one "Edit Condition" step.
     */
    func saveCondition(id: String, name: String, isLocation: Bool, isArchived: Bool, nowMs: Int64) throws 
    
    /**
     * Puts tasks in a board column as one "Move Task" step.
     */
    func setKanbanColumn(taskIds: [String], column: String?, nowMs: Int64) throws 
    
    /**
     * Archives or restores a list as one "Archive List" step.
     */
    func setListArchived(id: String, archived: Bool, nowMs: Int64) throws 
    
    /**
     * Places a task on the priority matrix as one "Move Task" step.
     */
    func setMatrixPosition(id: String, urgency: Int64?, importance: Int64?, nowMs: Int64) throws 
    
    /**
     * Reverses the most recent step; returns its label, or nothing when there
     * was nothing to undo.
     */
    func undo() throws  -> String?
    
    /**
     * The journal's named steps, newest first.
     */
    func undoHistory(limit: UInt32) throws  -> [UndoStep]
    
    /**
     * What undo would take back, phrased for a menu item.
     */
    func undoableLabel() throws  -> String?
    
    /**
     * Sets a list's name and colour as one "Edit List" step.
     */
    func updateList(id: String, name: String, colourHex: String?, nowMs: Int64) throws 
    
